script:
frappe.ui.form.on('Trip', {
	refresh(frm) {
		// your code here
		frm.add_custom_button("Check Vehicle", ()=>{
		    frappe.call({
             method: "fleet_management.api.check_vehicle",
                args: {
                vehicle: frm.doc.vehicle
            },
    callback: function(response) {
        let msg=response.message
        frappe.msgprint(msg)
    }
})
		})
	}
})
